        "BinId" integer,
        "PartName" character varying(200) NOT NULL,
        "PartNumber" character varying(100) NOT NULL,
        "CurrentStock" integer NOT NULL,
        "MinimumStock" integer NOT NULL,
        "LowStockNotificationSent" boolean NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL DEFAULT (now()),
        "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (now()),
        CONSTRAINT "PK_Part" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Part_Bin_BinId" FOREIGN KEY ("BinId") REFERENCES "Bin" ("Id") ON DELETE SET NULL,
        CONSTRAINT "FK_Part_Organization_OrganizationId" FOREIGN KEY ("OrganizationId") REFERENCES "Organization" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

