        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "OrganizationId" integer NOT NULL,
        "PartId" integer NOT NULL,
        "BinId" integer NOT NULL,
        "ActorType" integer NOT NULL,
        "ActorId" integer NOT NULL,
        "ActorName" character varying(200) NOT NULL,
        "QuantityDelta" integer NOT NULL,
        "PreviousStock" integer NOT NULL,
        "NewStock" integer NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL DEFAULT (now()),
        CONSTRAINT "PK_StockTransaction" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_StockTransaction_Bin_BinId" FOREIGN KEY ("BinId") REFERENCES "Bin" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_StockTransaction_Organization_OrganizationId" FOREIGN KEY ("OrganizationId") REFERENCES "Organization" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_StockTransaction_Part_PartId" FOREIGN KEY ("PartId") REFERENCES "Part" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

